// IMAGE: draws each living cell of [iBuffer0] as a hexagon that grows in when it's born, coloured
// by the generation it was born in. [zoom] on the timeline sets how many cells fit across.

// Distance from the centre of a hexagon, 0.5 at its edge.
float hexDist(vec2 p) {
  p = abs(p);
  return max(dot(p, normalize(vec2(1., SQRT3))), p.x);
}

// The cell a point is in, and where the point is in that cell.
ivec2 hexCell(vec2 p, out vec2 inCell) {
  vec2 r = vec2(1., SQRT3);
  vec2 a = mod(p, r) - 0.5 * r;
  vec2 b = mod(p - 0.5 * r, r) - 0.5 * r;
  inCell = dot(a, a) < dot(b, b) ? a : b;
  vec2 centre = p - inCell;
  return ivec2(round(centre.x * 2.), round(centre.y * 2. / SQRT3));
}

vec3 generationColor(float generation) {
  vec3 rainbow = 0.5 + 0.5 * cos(0.2 + generation * vec3(11.25, 7.5, 30.) + vec3(0.6, 2.7, 3.));
  return mix(rainbow, vec3(1.), 0.3);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
  vec2 inCell;
  ivec2 cell = hexCell(zoom * uv.yx, inCell);
  vec2 state = readCell(cell);
  // A new hexagon grows from its centre over its first second.
  float grown = smoothstep(0., 60., float(iFrame) - state.y);
  float border = max(0.04, zoom / 400.);
  float inside = 0.5 - hexDist(inCell);
  vec3 col = generationColor(state.y / float(STEPS_PER_GENERATION)) * state.x;
  col *= smoothstep(0.01, 0., (1. - grown) - inside + border);
  fragColor = vec4(col, 1.);
}

