// SHARED: the hexagonal grid, used by both tabs.
#define zoom iFloat0  // How many cells fit across the canvas's height.

// Steps between generations. [iFrame] moves on 60 times a second, so this is twice a second.
const int STEPS_PER_GENERATION = 30;
const float SQRT3 = 1.7320508;

// Cells are numbered with "doubled" coordinates: x + y is always even, and the six neighbours of
// a cell are 2 steps away along x, or 1 step along each of x and y. Cell (0, 0) is in the middle
// of the canvas, and is kept in the middle of [iBuffer0].
ivec2 bufferCentre() {
  return 2 * (ivec2(iResolution.xy) / 4);
}

const ivec2 NEIGHBOURS[6] = ivec2[6](
  ivec2(2, 0), ivec2(-2, 0), ivec2(1, 1), ivec2(-1, 1), ivec2(1, -1), ivec2(-1, -1));

// What [iBuffer0] holds for a cell: whether it's alive (x), and the step it was born on (y).
vec2 readCell(ivec2 cell) {
  ivec2 p = cell + bufferCentre();
  if (any(lessThan(p, ivec2(0))) || any(greaterThanEqual(p, ivec2(iResolution.xy)))) {
    return vec2(0.);
  }
  return texelFetch(iBuffer0, p, 0).xy;
}

