// iBuffer0: THE GROWTH. Each pixel is one hexagonal cell (see the [shared.glsl] tab). It starts with one
// living cell in the middle. Each generation, an empty cell with exactly one living neighbour comes
// alive, and a living cell stays alive for good.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  ivec2 cell = ivec2(fragCoord) - bufferCentre();
  vec2 here = readCell(cell);
  if (iFrame == 0) {
    // Born a second before the start, so it's fully grown from the first frame.
    fragColor = vec4(cell == ivec2(0) ? vec2(1., -60.) : vec2(0.), 0., 1.);
    return;
  }
  if (here.x > 0.5 || iFrame % STEPS_PER_GENERATION != 0) {
    fragColor = vec4(here, 0., 1.);
    return;
  }
  int living = 0;
  for (int i = 0; i < 6; i++) {
    living += int(readCell(cell + NEIGHBOURS[i]).x > 0.5);
  }
  fragColor = vec4(living == 1 ? vec2(1., float(iFrame)) : vec2(0.), 0., 1.);
}
